sys_security_acl.script:
answer = false;

// Administrator can view all leave balances
if (gs.hasRole('x_2132473_leave_0.admin')) {
    answer = true;
}

// Employee can view their own leave balance
else if (gs.hasRole('x_2132473_leave_0.employee')) {
    answer = current.getValue('employee') == getEmployeeId();
}

// Manager can view balances belonging to their team
else if (gs.hasRole('x_2132473_leave_0.manager')) {
    var employeeGR = new GlideRecord('x_2132473_leave_0_employee');

    if (employeeGR.get(current.getValue('employee'))) {
        var managerId = getEmployeeId();

        answer = employeeGR.getValue('manager') == managerId;
    }
}

function getEmployeeId() {
    var emp = new GlideRecord('x_2132473_leave_0_employee');
    emp.addQuery('user', gs.getUserID());
    emp.addQuery('active', true);
    emp.setLimit(1);
    emp.query();

    if (emp.next()) {
        return emp.getUniqueValue();
    }

    return '';
}
